rection:column;min-height:0;min-width:0}.editor-panel{border-right:1px solid var(--border);background:#12181f}.panel-heading{height:43px;flex-shrink:0;display:flex;justify-content:space-between;align-items:center;padding:8px 16px;border-bottom:1px solid var(--border);color:var(--dim);font-size:10px;letter-spacing:1px}.panel-heading>label{display:flex;align-items:center;gap:12px;min-width:0}.panel-heading input{background:none;border:0;padding:4px;color:var(--text);letter-spacing:0;width:200px;font-size:12px}.panel-heading button{padding:2px 8px}.filebar{display:flex;gap:10px;align-items:center;padding:9px 14px;border-bottom:1px solid var(--border)}select,input[type=text],input[type=url]{background:var(--bg);border:1px solid var(--border);border-radius:4px;padding:7px;min-width:0}#file{flex:1}.entry-label{font-size:10px;color:var(--dim);display:flex;align-items:center;gap:7px}.entry-label select{font-size:11px;max-width:180px}.editor-wrap{flex:1;min-height:0;display:flex;overflow:hidden;padding-top:17px}#line-numbers{color:#4e6072;text-align:right;user-select:none;margin:0;line-height:1.7;padding:0 12px;width:48px;overflow:hidden;font-size:13px}#editor{flex:1;resize:none;border:0;background:transparent;outline:none;padding:0 18px 24px 3px;line-height:1.7;tab-size:2;color:#c6e0db;font-size:13px;white-space:pre;overflow:auto}.editor-footer{display:flex;justify-content:space-between;gap:10px;border-top:1px solid var(--border);padding:8px 14px;font-size:10px;color:var(--dim)}.score-scroll{flex:1;overflow:auto;min-height:150px;position:relative}.tracks{padding:0 16px}.track{padding:13px 0 10px;border-bottom:1px solid var(--border)}.track-head{display:flex;gap:10px;align-items:center;margin-bottom:8px;font-size:12px}.track-head .track-id{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.track-head button{font-size:10px;padding:3px 8px;margin-left:auto}.track-head button[aria-pressed=true]{color:var(--accent);border-color:var(--accent)}.track-head .note-count{font-