fset:-5px}@media(max-width:1000px){.tag{display:none}.topbar{padding:12px 14px}.brand>.tag{display:none}nav{flex-wrap:wrap}.transport{padding:10px 14px}.volume{display:none}.time{margin:0 4px}footer #link-state{display:none}}@media(max-width:760px){body{height:auto;min-height:100dvh}.topbar{height:auto;align-items:flex-start;flex-direction:column;gap:12px}nav{width:100%}nav button{flex:1;padding:7px}.transport{gap:6px}main{display:flex;flex-direction:column;min-height:0}.editor-panel{height:56dvh;min-height:330px;border-right:0;border-bottom:1px solid var(--border)}.output-panel{min-height:400px}.score-scroll{min-height:220px;max-height:400px}footer{flex-wrap:wrap;line-height:1.5}.entry-label select{max-width:130px}}
